    24→  "ul > li > div > div.trackItem__content.sc-truncate > a:last-of-type";
    25→
    26→const DOWNLOAD_DOMAINS = [
    27→  "hypeddit.com",
    28→  "bandcamp.com",
    29→  "toneden.io",
    30→  "fanlink.to",
    31→  "distrokid.com",
    32→  "soundcloud.com/download",
    33→  "dropbox.com",
    34→  "drive.google.com",
    35→  "mediafire.com",
    36→  "sendspace.com",
    37→  "wetransfer.com",
    38→];
    39→
    40→const DOWNLOAD_KEYWORDS = ["download", "free", "buy", "get it", "grab", "dl"];
    41→
    42→function decodeSCGate(href: string): string {
    43→  try {
    44→    const parsed = new URL(href);
    45→    if (parsed.hostname === "gate.sc") {
    46→      const u = parsed.searchParams.get("url");
    47→      return u ? decodeURIComponent(u) : href;
    48→    }
    49→    return href;
    50→  } catch {
    51→    return href;
    52→  }
    53→}
    54→
    55→function isDownloadLink(decodedUrl: string, linkText: string): boolean {
    56→  const lowerUrl = decodedUrl.toLowerCase();
    57→  const lowerText = linkText.toLowerCase();
    58→  const matchesDomain = DOWNLOAD_DOMAINS.some((d) => lowerUrl.includes(d));
    59→  const matchesKeyword = DOWNLOAD_KEYWORDS.some(
    60→    (k) => lowerText.includes(k) || lowerUrl.includes(k)
    61→  );
    62→  return matchesDomain || matchesKeyword;
    63→}
    64→
    65→/**
    66→ * Try to read download/purchase signals from window.__sc_hydration (sound entry).
    67→ * Returns null if hydration is missing, not an array, or has no "sound" entry.
    68→ */
    69→function tryParseHydration(): HydrationResult | null {
    70→  try {
    71→    const win = window as Window & { __sc_hydration?: unknown };
    72→    const hydration = win.__sc_hydration;
    73→    if (!Array.isArray(hydration)) return null;
    74→    const soundEntry = hydration.find(
    75→      (entry: { hydratable?: string }) => entry?.hydratable === "sound"
    76→    );
    77→    if (!soundEntry || typeof soundEntry !== "object" || !("data" in soundEntry)) return null;
    78→    const data = (soundEntry as { data: ScHydrationSound }).data;
    79→    if (!data || typeof data !== "object") return null;
    80→
    81→    const directDownloadAvailable = data.downloadable === true;
    82→    const purchaseUrl = data.purchase_url;
    83→    const hasPurchase = typeof purchaseUrl === "string" && purchaseUrl.length > 0;
    84→    const freeGatedBuyLink = hasPurchase ? decodeSCGate(purchaseUrl) : "";
